suitehelp.setHiddenElement = function () {
   /*
    add show/hide link to element 
    in order to hide an element add "output class = hideelement" to the wanted element
    if its an image - add the output class to figure 
*/

    //adding a hide/show link
    $('figure.hideelement > .image').before('<a class="hidelink" style="display:block;margin-bottom:6px;">Show more</a>');
	$('figure.hideelement > .ol').slideToggle();
    $('.hideelement:not(figure):not(ol):not(ul)').before('<a class="hidelink">Show more</a>');
    $('ol.hideelement').before('<a class="hidelink" style="display:block;margin-bottom:6px;">Show more</a>');
    $('ul.hideelement').before('<a class="hidelink" style="display:block;margin-bottom:6px;">Show more</a>');


    $('.hidelink').on( "click", function( event ) {
    
    // figure show/hide link is a child of hidden-element 
    if($('figure.hideelement').find($(this)).length > 0)
    {
        $(this).siblings('img').slideToggle();
		
		if($('figure.hideelement > .ol'))
		{
			$(this).siblings('ol').slideToggle();
		}
			
		$(this).toggleClass("visible-element");
		if($(this).hasClass('visible-element'))
		   $(this).text('Show less');
		else
		   $(this).text('Show more');

    }
   // show/hide link is a sibling of hidden-element 
    else 
    {
        $(this).next('.hideelement').slideToggle();
        $(this).toggleClass("visible-element");
        if($(this).hasClass('visible-element'))
            $(this).text('Show less');
        else
            $(this).text('Show more');
    }
       
    });
};
//scrolls to current topic in leftbar.
suitehelp.scrollToCurrent = function () {
    "use strict";
     //scrolling the open leftbar nav to the current topic
        setTimeout(function(){  
        if(suitehelp.getCurrentPane().attr("id")==='toc_pane')
        {  
            if($(".current").offset())
            {
                var offset=50;
                var elTop=$(".current").offset().top-$(".nav-secondary#toc_nav > nav > ul .mCSB_container").offset().top;
                $(".nav-secondary.in > nav > ul").mCustomScrollbar('scrollTo', elTop);
            }
         }},550);
         
          setTimeout(function(){
         if(suitehelp.getCurrentPane().attr("id")==='index_pane')
        { 
            if(isNaN($(".curr_index").offset().top)===false)
            {
                 var offset=50;
                 var elTop=$(".curr_index").offset().top-$(".nav-secondary#index_nav > nav > ul .mCSB_container").offset().top;
                $(".nav-secondary#index_nav > nav > ul").mCustomScrollbar('scrollTo', elTop);
            }
         
          }},550);
          
          setTimeout(function(){
         if(suitehelp.getCurrentPane().attr("id")==='glossary_pane')
        { 
       
            if(isNaN($(".curr_gloss").offset().top)===false)
            {
                 var offset=50;
                 var elTop=$(".curr_gloss").offset().top-$(".nav-secondary#glossary_nav > nav > ul .mCSB_container").offset().top;
                $(".nav-secondary#glossary_nav > nav > ul").mCustomScrollbar('scrollTo', elTop);
            }
         
          }},550);
          
            setTimeout(function(){
        if(suitehelp.getCurrentPane().attr("id")==='search_pane')
        { 
	// alissa added
			if (elTop) {
			
            if(isNaN($(".nav-secondary#search_nav > nav > ul .current").offset().top)===false)
            {
                 var offset=50;
                 var elTop=$(".nav-secondary#search_nav > nav > ul .current").offset().top-$(".nav-secondary#search_nav > nav > ul .mCSB_container").offset().top;
                $(".nav-secondary#search_nav > nav > ul").mCustomScrollbar('scrollTo', elTop);
            }
         }
          }},550);
};

