suitehelp.getHideFrame = function () {
    "use strict";
  if ($("body").hasClass('hideframe')){
    return true;
    }
};
suitehelp.nonAjaxRedirect = function (url) {
    "use strict";

    var q = $("#search_textbox").val();
    var currentPane = suitehelp.getCurrentPane().attr("id");
    var currentIndex = suitehelp.getCurrentIndex().attr("id");
    var hideframe = suitehelp.getHideFrame();
   
    if (q) {
        url = suitehelp.addQueryStringToURL(url, "q", q);
    } else {
        url = suitehelp.addQueryStringToURL(url, "local", true);
    }

   /* if ($("body").hasClass("hide-nav")) {
        url = suitehelp.addQueryStringToURL(url, "hidenav", "true");
    }*/

    //Allows suitehelp to persist the glossary and index
    url = suitehelp.addQueryStringToURL(url, "nav", currentPane);
    if(currentIndex){
    url =suitehelp.addQueryStringToURL(url, "currin", currentIndex);
    }
    if(hideframe){
    url =suitehelp.addQueryStringToURL(url, "hideframe", hideframe);
    }
    document.location.href = url;
    return false;
};
suitehelp.checkScroll = function () {
    "use strict";

    var scroll;

    function getScrollValue(key) {
        suitehelp.queryString = {};
        var query = window.location.search.substring(1),
            vars,
            i,
            pair,
            hashScroll,
            hash;
        if (!query) {
            hash = window.location.hash;
            hashScroll=hash.slice(hash.indexOf('#') + 1);
            query = hash.slice(hash.indexOf('?') + 1);
            if(hashScroll){
                 return hashScroll;
            }
           
        }
        vars = query.split("&");
        for (i = 0; i < vars.length; i += 1) {
            pair = vars[i].split("=");
            suitehelp.queryString[pair[0]] = unescape(pair[1]);
        }
        return suitehelp.queryString[key];
    }
    scroll = getScrollValue("scroll");
   
    if (scroll) {
        $("#thumbnailDialog" + " "+ "#" + scroll)[0].scrollIntoView();
    } else {
        $("article").scrollTop(0);
        if (suitehelp.customScrollBar) {
            (suitehelp.centerScroll).data('jsp').scrollTo(1, 1);
        }
    }
};
suitehelp.loadChildrenForPrintAll = function (top, dest, andThen) {
    "use strict";

    var firstLi = top.children("ul").children("li").first(),
        id,
        contentHtml,
        href;

    function go(li) {
        if (li.length === 0) {
            return andThen();
        }

        id = li.attr("id");
        dest.append("<div id='printall-" + id + "'/>");
        href = li.children("a").attr("href");

        //If li is a topicgroup with no page reference, don't make ajax call
        if (!href) {
            suitehelp.loadChildrenForPrintAll(li, $("#printall-" + id), function () {
                go(li.next("li"));
            });
            return;
        }

        //First resolve all urls before loading data for printing
        $.ajax({
            url: href,
            success: function (data) {
                // Replace all relative URLs with absolute URLs
                data = suitehelp.makeAbsoluteURLs(li.children("a").attr("href"), data);
                contentHtml = $(data).find("article").html();
                document.getElementById("thumbnailDialog").scrollTop=0;
                $('[id="printall-' + id + '"]').html(contentHtml);
                suitehelp.loadChildrenForPrintAll(li,  $('[id="printall-' + id + '"]'), function () {
                    go(li.next("li"));
                });
            }
        });
    }
    go(firstLi);
};